# -*- coding: utf-8 -*-
"""槽位检查：判断「库里有没 有这个属性的答案」，不靠分数。

## 解决什么问题

实测：问「我在哪工作」，库里确实没有任何工作信息，但最高分仍有 0.605。
那条记忆是「他说：改代码；我回：明天再核对结果」——语义相似度 0.569，
足够高到能进 Top-1，但它答不了这个问题。

分数分不开（正例中位 0.656 / 无答案 0.605，只差 0.05），所以不能靠阈值拒答。
这个模块换一个判据：**问题问的是某个属性，库里有没有提到过这个属性？**

与分数完全无关，因此不会被「语义有点像」干扰。

## 为什么不会误杀换说法

只对**能判出槽位**的问题检查（实测 29 条正例里只有 9 条能判出）。
判不出槽位 → 直接放行；已识别的槽位逐条检查主体和直接证据。

## 已知限制

- 槽位表是手工维护的，新增属性要加规则
- 覆盖面有限（实测 31%），不是万能的「敢说没有」
- 证据规则写宽了会漏判，写窄了会误判；以「零误伤」为优先（宁可漏判）

## 用法

    from slot_check import find_slot, has_evidence, verdict
    slot = find_slot("我在哪工作")          # → "工作"
    ok, frag = has_evidence(slot, corpus)   # → (False, None)
    verdict(slot, corpus)                   # → ("none", "库里没有工作信息")
"""

import re

# 问题 → 在问哪个槽位（按顺序匹配，先命中先返回）
QUERY_SLOTS = [
    ("发布记录", [r"(?:我|你|他|她).{0,16}(?:发过|分享|发布|上传).{0,16}(?:视频|作品|帖子|短视频|微博|卡片)",
                    r"(?:短视频|微博|B站).{0,8}(?:发过|分享过|发布过|上传过)"]),
    ("运行依赖", [r"(?:关机|断网|离线|电脑.{0,3}关).{0,12}(?:你|还|能|会)",
                    r"(?:半夜|夜里|晚上).{0,5}你.{0,5}(?:在吗|在线|回复|回消息)",
                    r"睡(?:着|觉).{0,8}你.{0,5}(?:怎样|怎么样|回复|回消息)"]),
    ("工作", [r"在哪工作", r"工作单位", r"干什么工作", r"做什么工作",
              r"在哪(?:儿|里)?(?:上班|工作|任职)", r"职业", r"哪家公司", r"什么职位",r"职位.{0,5}(?:什么|啥)"]),
    ("住址", [r"住哪", r"在哪住", r"住哪儿", r"住在哪", r"家在", r"哪个区", r"哪个城市", r"我人在哪"]),
    ("生日", [r"生日.{0,5}(?:哪天|几号|几月|什么时候)", r"(?:哪天|几号|几月).{0,4}生日", r"几号生", r"哪天生", r"出生日期"]),
    ("年龄", [r"几岁", r"多大", r"年龄", r"多少岁", r"岁数", r"年纪"]),
    ("名字", [r"我叫什么", r"我的名字", r"叫我什么", r"怎么称呼我"]),
    ("偏好_吃", [r"爱吃", r"喜欢吃什么", r"不吃什么", r"口味", r"喜欢什么(?:饮食|食物)", r"饮食偏好"]),
    ("偏好_物", [r"喜欢什么", r"最喜欢", r"爱看什么", r"爱玩什么"]),
    ("怕", [r"怕什么", r"怕啥", r"害怕什么"]),
    ("家人", [r"有几个家人", r"家里有谁", r"爸妈是谁", r"父母是谁"]),
]

# 每个槽位：库里要出现什么词，才算「有这条信息」
#
#   ⚠️ 这些规则是「宽进严出」的：宁可多认成有证据（漏判 → 照常答，只是答错），
#      也不要少认（误判 → 该答的说没有，用户直接觉得她失忆）。
#      实测这套规则在 29 条正例上零误判。
SLOT_EVIDENCE = {
    "发布记录": [r"(?:发了|发过|发表|发布|上传|分享).{0,25}(?:视频|作品|帖子|卡片)",
                  r"(?:短视频|微博|B站).{0,30}(?:发了|发过|发布|上传|分享)"],
    "运行依赖": [r"(?:电脑|设备|机器|进程|网络|服务).{0,8}(?:关|断|停).{0,20}(?:睡|不能|无法|离线|喊不了)",
                  r"(?:离线|关机|断网).{0,16}(?:不能|无法|不再).{0,8}(?:回复|运行|连接|发消息)"],
    "工作": [r"工作单位", r"公司在", r"任职于", r"就职于", r"入职",
             r"他.{0,4}在.{2,10}(?:上班|工作)", r"职业是", r"岗位是", r"职位是"],
    "住址": [r"住在", r"家在", r"搬到.{1,10}(?:区|市|路)"],
    "生日": [r"生日.{0,6}\d", r"\d{1,2}\s*月\s*\d{1,2}\s*[日号]", r"生日是"],
    "年龄": [r"\d{1,2}\s*岁"],
    "名字": [r"我的大名", r"我的小名", r"大名是"],
    "偏好_吃": [r"喜欢吃", r"喜欢.{0,6}饮食", r"爱吃", r"不喜欢吃", r"不吃", r"口味", r"冰的", r"甜的", r"辣的"],
    "偏好_物": [r"喜欢.{0,8}(?:看|玩|听|做|穿)", r"最怕", r"爱看", r"爱玩"],
    "怕": [r"怕", r"害怕", r"不敢", r"炸毛"],
    "家人": [r"父亲是", r"母亲是", r"父母", r"家里人"],
}

_UNKNOWN = (True, None)


def find_slot(query: str):
    """这一问在问哪个槽位。返回 (槽位, 命中的说法)；判不出返回 (None, None)。"""
    t = str(query or "")
    if not t:
        return None, None
    for slot, pats in QUERY_SLOTS:
        for p in pats:
            if re.search(p, t):
                return slot, p
    return None, None


def has_evidence(slot: str, corpus) -> tuple:
    """库里有没有这个槽位的证据。返回 (有没有, 命中的片段)。

    slot 为 None 或不在表里 → 一律返回 True（放行，不检查）。
    corpus 可以是字符串列表，也可以是带 .content 的对象列表。
    """
    if not slot:
        return _UNKNOWN
    pats = SLOT_EVIDENCE.get(slot)
    if not pats:
        return _UNKNOWN
    for item in corpus or []:
        content = item if isinstance(item, str) else str(getattr(item, "content", "") or "")
        if not content:
            continue
        for p in pats:
            if re.search(p, content):
                return True, content[:60]
    return False, None


def verdict(query: str, corpus) -> tuple:
    """综合判定。返回 (档位, 理由)。

    档位取值：
        "none"     —— 能判出槽位，且库里没有该槽位证据 → 应当拒答
        "unknown"  —— 判不出槽位 → 不检查，调用方按原逻辑走
        "ok"       —— 有证据 → 调用方按原逻辑走
    """
    slot, pat = find_slot(query)
    if not slot:
        return "unknown", "判不出槽位，放行"
    ok, frag = has_evidence(slot, corpus)
    if ok:
        return "ok", "有%s证据：%s" % (slot, frag)
    return "none", "库里没有%s信息" % slot


# ═══════════════════════════════════════════════════════════════════
# 自检
# ═══════════════════════════════════════════════════════════════════
def selftest():
    """槽位判定与证据检查。不读盘、不联网。"""
    # ① 能判出槽位
    assert find_slot("我在哪工作")[0] == "工作"
    assert find_slot("我生日是哪天")[0] == "生日"
    assert find_slot("我住哪")[0] == "住址"

    # ② 判不出就是 None，不是猜一个
    assert find_slot("今天天气怎么样")[0] is None
    assert find_slot("")[0] is None

    # ③ 库里没证据 → none（这是本模块存在的理由：分数高但不能答）
    #   注意 verdict() 第一个参数是**问句**，不是槽位名 —— 它内部再判槽位。
    state, why = verdict("我在哪工作", ["他说：改代码；我回：那你去弄"])
    assert state == "none", (state, why)

    # ④ 库里有证据 → ok
    assert verdict("我在哪工作", ["他在一家公司上班，职业是工程师"])[0] == "ok"
    assert verdict("我生日是哪天", ["他生日是 10 月 25 日"])[0] == "ok"

    # ⑤ 判不出槽位 → unknown，一律放行（宁可漏判，不误杀）
    assert verdict("今天天气怎么样", [])[0] == "unknown"

    # ⑥ has_evidence 支持字符串列表与带 .content 的对象列表
    class Row:
        def __init__(self, c):
            self.content = c
    assert has_evidence("住址", [Row("他住在示例城市")])[0] is True
    assert has_evidence(None, []) == (True, None)

    print("slot_check.py selftest OK")
    print("  %d 个槽位 / 判不出的放行" % len(SLOT_EVIDENCE))


if __name__ == "__main__":
    selftest()
